CREATE TABLE actions (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(255) NOT NULL, name VARBINARY(512) NOT NULL, trigger_id VARCHAR(64) NOT NULL, runtime VARCHAR(32) NOT NULL, code LONGTEXT NOT NULL, dependencies LONGTEXT NOT NULL, secrets LONGTEXT NOT NULL, draft_build_id VARBINARY(255) NOT NULL, deployed_version_id VARBINARY(255) NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,id), UNIQUE (tenant_id,name), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX actions_by_trigger ON actions (tenant_id,trigger_id,created_at,id);
CREATE TABLE action_versions (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(255) NOT NULL, action_id VARBINARY(255) NOT NULL, number INTEGER NOT NULL, code LONGTEXT NOT NULL, runtime VARCHAR(32) NOT NULL, build_id VARBINARY(255) NOT NULL, dependencies LONGTEXT NOT NULL, secrets LONGTEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,id), UNIQUE (tenant_id,action_id,number), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE action_builds (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(255) NOT NULL, status VARCHAR(16) NOT NULL, requested LONGTEXT NOT NULL, resolved LONGTEXT NOT NULL, errors LONGTEXT NOT NULL, artifact_sha256 VARCHAR(128) NOT NULL, built_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,id), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE action_artifacts (tenant_id VARCHAR(64) NOT NULL, build_id VARBINARY(255) NOT NULL, data LONGBLOB NOT NULL, PRIMARY KEY (tenant_id,build_id), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE TABLE action_bindings (tenant_id VARCHAR(64) NOT NULL, trigger_id VARCHAR(64) NOT NULL, position INTEGER NOT NULL, id VARBINARY(255) NOT NULL, action_id VARBINARY(255) NOT NULL, display_name LONGTEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,trigger_id,position), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX action_bindings_by_action ON action_bindings (tenant_id,action_id);
CREATE TABLE action_executions (tenant_id VARCHAR(64) NOT NULL, id VARBINARY(255) NOT NULL, trigger_id VARCHAR(64) NOT NULL, status VARCHAR(32) NOT NULL, results LONGTEXT NOT NULL, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,id), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX action_executions_by_created ON action_executions (created_at);
CREATE TABLE action_continues (tenant_id VARCHAR(64) NOT NULL, state_hash VARBINARY(255) NOT NULL, session_id LONGTEXT NOT NULL, sealed LONGBLOB NOT NULL, expires_at BIGINT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY (tenant_id,state_hash), FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
CREATE INDEX action_continues_by_expiry ON action_continues (expires_at);
